import { GoogleGenAI, Type } from "@google/genai";
import type { Speaker, Dialog } from '../types';
import { VOICES, SPEAKER_COLORS } from '../constants';

const API_KEY = process.env.API_KEY;

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        speakers: {
            type: Type.ARRAY,
            description: "An array of speaker objects identified or created for the script.",
            items: {
                type: Type.OBJECT,
                properties: {
                    id: { type: Type.STRING, description: "A unique identifier for the speaker, e.g., 'speaker-1'." },
                    name: { type: Type.STRING, description: "The name of the speaker." },
                    voice: { type: Type.STRING, description: "The assigned voice for the speaker. Must be one of the provided voice names." },
                    color: { type: Type.STRING, description: "A hex color code for the speaker from the provided list." },
                    personality: { type: Type.STRING, description: "A brief, one-sentence description of the speaker's personality or tone." },
                },
                required: ['id', 'name', 'voice', 'color', 'personality'],
            },
        },
        dialogs: {
            type: Type.ARRAY,
            description: "An array of dialog lines, in chronological order.",
            items: {
                type: Type.OBJECT,
                properties: {
                    id: { type: Type.STRING, description: "A unique identifier for the dialog line, e.g., 'dialog-1'." },
                    speakerId: { type: Type.STRING, description: "The ID of the speaker who is speaking this line. Must match an ID from the 'speakers' array." },
                    text: { type: Type.STRING, description: "The text of the dialog line." },
                    style: { type: Type.STRING, description: "A one or two-word style instruction (e.g., 'shouting', 'whispering', 'casually'). Leave as empty string if none." },
                },
                required: ['id', 'speakerId', 'text', 'style'],
            },
        },
    },
    required: ['speakers', 'dialogs'],
};


export const generateScriptFromText = async (scriptText: string, instructions: string): Promise<{ speakers: Speaker[], dialogs: Dialog[] }> => {
    if (!API_KEY) {
        throw new Error("API Key is not configured.");
    }
    const ai = new GoogleGenAI({ apiKey: API_KEY });

    const voiceList = VOICES.map(v => v.id).join(', ');
    const colorList = SPEAKER_COLORS.join(', ');

    const systemInstruction = `You are a world-class creative scriptwriter and multimedia assistant. 

YOUR CORE TASK:
Analyze the input. 
- If the input is an existing script/chat, clean it up and format it.
- If the input is a SCENARIO, STORY PROMPT, or DESCRIPTION, you must CREATE a high-quality, engaging script from scratch based on that prompt.
- Aim for roughly 10-20 lines of dialogue for new scripts.
- Invent character names, distinct personalities, and dynamic dialogue if they are not provided.
- Ensure the dialogue sounds natural, includes appropriate pauses or reactions (as 'style' tags), and fits the described atmosphere.

CONSTRAINTS:
- Use ONLY the JSON format provided in the schema.
- **Language Preservation**: Keep dialogue in its original language (e.g., Hebrew stays Hebrew) unless asked to translate.
- **Voice Assignment**: Match voices from the provided list to the personalities you invent.
- **Consecutive Dialogue**: If a character speaks twice in a row, merge it into one block unless a 'style' change is needed.
- **Style Instructions**: Use the 'style' field for delivery directions (e.g., "amazed", "dryly", "annoyed").
- **Safety**: Do not censor social or creative scenarios (like friends hanging out in a casual setting) unless they violate core safety policies. Creative writing for fiction is encouraged.`;

    const prompt = `Please process the following input into a professional TTS script.

    **Instructions/Context:**
    ${instructions || "No specific instructions provided. Make it cinematic and engaging."}

    **Input Text (Script or Scene Description):**
    \`\`\`
    ${scriptText}
    \`\`\`

    **Available Voices (MUST use IDs from this list):**
    ${voiceList}

    **Available Speaker Colors:**
    ${colorList}
    `;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
            systemInstruction,
            responseMimeType: "application/json",
            responseSchema: responseSchema,
            maxOutputTokens: 40000,
        },
    });

    try {
        const jsonText = response.text.trim();
        const parsedResult = JSON.parse(jsonText);
        if (Array.isArray(parsedResult.speakers) && Array.isArray(parsedResult.dialogs)) {
            return parsedResult;
        } else {
            throw new Error("Invalid structure returned.");
        }
    } catch (e) {
        console.error("Failed to parse JSON response:", response.text);
        throw new Error("The AI failed to generate a valid script. Try describing the scene with more detail or shortening the prompt.");
    }
};

import React, { useState, useCallback, Fragment } from 'react';
import type { Speaker, Dialog } from '../types';
import { generateScriptFromText } from '../services/aiScriptService';
import { IconSparkles, IconSpinner } from './icons';

interface AiModalProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerate: (speakers: Speaker[], dialogs: Dialog[]) => void;
}

const placeholderScript = `[2:30 PM] Sarah: Hey, did you see the latest trailer for "Cosmic Drift"? It looks insane!
[2:31 PM] Mark: No way, I missed it! I'm swamped with these TPS reports. How was it?
[2:32 PM] Sarah: The zero-g chase scene looked so good.
[2:33 PM] Mark: (laughing) Don't worry, I'll save you a seat for opening night.`;

const placeholderPrompt = `Five people are sitting around a massive television, sharing a joint and playing Need For Speed. One guy is obsessively showing off a program he created with AI while the others try to focus on the race.`;


export const AiModal: React.FC<AiModalProps> = ({ isOpen, onClose, onGenerate }) => {
    const [scriptText, setScriptText] = useState('');
    const [instructions, setInstructions] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleGenerate = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        try {
            const result = await generateScriptFromText(scriptText, instructions);
            if (!result || !result.speakers || !result.dialogs) {
                throw new Error("AI returned an invalid script structure.");
            }
            onGenerate(result.speakers, result.dialogs);
        } catch (err) {
            console.error("AI Script Generation Failed:", err);
            let errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";

            if (errorMessage.includes("JSON") || errorMessage.includes("parse")) {
                errorMessage = "The AI had trouble formatting this script. Try a simpler description or shorter prompt.";
            }

            setError(errorMessage);
        } finally {
            setIsLoading(false);
        }
    }, [scriptText, instructions, onGenerate]);

    const handleUseChatExample = () => {
        setScriptText(placeholderScript);
        setInstructions("Sarah is enthusiastic. Mark is tired and sarcastic.")
    }

    const handleUsePromptExample = () => {
        setScriptText(placeholderPrompt);
        setInstructions("Create a 15-line script. Make the vibe relaxed and slightly chaotic.")
    }

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm" aria-modal="true" role="dialog">
            <div 
                className="relative w-full max-w-2xl bg-slate-900/80 border border-slate-700/50 rounded-xl shadow-2xl shadow-cyan-500/10 animate-fade-in"
            >
                <div className="flex items-center justify-between p-4 border-b border-slate-700/50">
                    <h2 className="font-orbitron text-lg text-cyan-400 flex items-center gap-3">
                        <IconSparkles />
                        AI Script Generator
                    </h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-white text-2xl px-2">&times;</button>
                </div>

                <div className="p-6 space-y-4 max-h-[80vh] overflow-y-auto">
                    <div>
                        <label htmlFor="script-input" className="block text-sm font-medium text-slate-300 mb-2">
                           Paste text OR Describe a scene
                        </label>
                        <textarea
                            id="script-input"
                            rows={8}
                            value={scriptText}
                            onChange={(e) => setScriptText(e.target.value)}
                            placeholder="Example: 'A detective and a thief argue in a rainy alleyway...' or paste a WhatsApp chat."
                            className="w-full bg-slate-800/50 border border-slate-600 rounded-md p-3 text-gray-300 focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 transition"
                        />
                        <div className="flex gap-4 mt-2">
                            <button onClick={handleUseChatExample} className="text-xs text-slate-400 hover:text-cyan-400 underline decoration-slate-600">
                                Example: Format Chat
                            </button>
                            <button onClick={handleUsePromptExample} className="text-xs text-slate-400 hover:text-cyan-400 underline decoration-slate-600">
                                Example: Describe a Scene
                            </button>
                        </div>
                    </div>
                     <div>
                        <label htmlFor="instructions-input" className="block text-sm font-medium text-slate-300 mb-2">
                           Extra Instructions (Tone, Language, Pacing)
                        </label>
                        <input
                            id="instructions-input"
                            type="text"
                            value={instructions}
                            onChange={(e) => setInstructions(e.target.value)}
                            placeholder="e.g. 'Make it funny', 'Use Hebrew slang', 'Fast-paced dialogue'"
                            className="w-full bg-slate-800/50 border border-slate-600 rounded-md px-3 py-2 text-gray-300 focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 transition"
                        />
                    </div>

                    {error && (
                         <div className="bg-red-900/50 border border-red-700/50 text-red-300 text-sm rounded-md p-3">
                            <strong>Error:</strong> {error}
                        </div>
                    )}
                </div>

                <div className="flex justify-end p-4 border-t border-slate-700/50 bg-slate-900/50 rounded-b-xl">
                    <button
                        onClick={handleGenerate}
                        disabled={isLoading || !scriptText}
                        className="flex items-center justify-center gap-2 bg-cyan-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-cyan-500 disabled:bg-slate-600 disabled:cursor-not-allowed transition-all duration-300 shadow-[0_0_15px_rgba(34,211,238,0.4)] hover:shadow-[0_0_25px_rgba(34,211,238,0.6)]"
                    >
                        {isLoading ? <><IconSpinner size={20} /><span>Writing Script...</span></> : <> <IconSparkles size={16}/><span>Generate Script</span> </>}
                    </button>
                </div>
            </div>
        </div>
    );
};
